"use client";

import { useEffect, useRef } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { createWeatherLoader } from "./three/WeatherRenderer";

interface ThreeSceneProps {
  settings: {
    zoom: number;
    buildings: boolean;
    traffic: boolean;
    weather: boolean;
    terrain: boolean;
    nightMode: boolean;
  };
}

export default function ThreeScene({ settings }: ThreeSceneProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const controlsRef = useRef<any>(null);
  const frameRef = useRef<number | null>(null);

  const loadersRef = useRef(new Map<string, ChunkLoader>());

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const envBase = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";
    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0");

    const [centerX, centerZ] = proj4("EPSG:4326", "EPSG:3857", [
      startLon,
      startLat,
    ]);

    // Renderer
    const renderer = createRenderer(container);
    renderer.physicallyCorrectLights = true;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;
    rendererRef.current = renderer;

    // Camera
    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = 60;
    camera.position.set(0, 800, 800);
    camera.updateProjectionMatrix();
    cameraRef.current = camera;

    // Controls
    const controls = createControls(camera, renderer.domElement);
    controls.target.set(0, 0, 0);
    controls.update();
    controlsRef.current = controls;

    // Scene
    const { scene, cube } = createScene();
    sceneRef.current = scene;

    // Освещение
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(800, 1500, 600);
    scene.add(dirLight);

    const ambLight = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambLight);

    // Raycast
    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    // Ground
    const groundGeom = new THREE.PlaneGeometry(500000, 500000, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.9,
      metalness: 0,
    });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    // Loaders
    const buildingsLoader = new ChunkLoader(scene, {
      url: `${envBase}/chunk/buildings`,
      centerOffset: [centerX, centerZ],
      layerType: "buildings",
    });
    const roadsLoader = new ChunkLoader(scene, {
      url: `${envBase}/chunk/roads`,
      centerOffset: [centerX, centerZ],
      layerType: "roads",
    });
    const weatherLoader = createWeatherLoader(scene, {
      url: `${envBase}/weather/area`,
      centerOffset: [centerX, centerZ],
      tileSize: 50,
      elevationAboveGround: 0.2,
      opacity: 0.7,
      mode: "temperature",
    });

    loadersRef.current.set("buildings", buildingsLoader);
    loadersRef.current.set("roads", roadsLoader);
    loadersRef.current.set("weather", weatherLoader);

    // Animation loop
    const loop = () => {
      if (!rendererRef.current || !sceneRef.current) return;

      // Подстраиваем свет под камеру
      dirLight.position.set(
        camera.position.x + 500,
        camera.position.y + 1500,
        camera.position.z + 500
      );

      controls.update();
      renderer.render(scene, camera);

      frameRef.current = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      if (!renderer || !camera) return;
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);
    container.appendChild(renderer.domElement);

    return () => {
      cancelAnimationFrame(frameRef.current!);
      window.removeEventListener("resize", handleResize);
      try {
        cleanupRaycast();
      } catch {}
      renderer.dispose();
      groundGeom.dispose();
      groundMat.dispose();
    };
  }, []);

  // Реакция на изменение settings
  useEffect(() => {
    const camera = cameraRef.current;
    const scene = sceneRef.current;
    if (!camera || !scene) return;

    // Масштаб камеры
    camera.zoom = settings.zoom;
    camera.updateProjectionMatrix();

    // Ночной режим
    if (settings.nightMode) {
      scene.background = new THREE.Color(0x111111);
      scene.fog = new THREE.Fog(0x111111, 100, 2000);
    } else {
      scene.background = new THREE.Color(0xbfd9ff);
      scene.fog = new THREE.Fog(0xbfd9ff, 100, 2000);
    }

    // Слои
    const layers = {
      buildings: loadersRef.current.get("buildings"),
      traffic: loadersRef.current.get("roads"),
      weather: loadersRef.current.get("weather"),
    };

    if (layers.buildings?.meshGroups) {
      layers.buildings.meshGroups.forEach((group) => {
        group.visible = settings.buildings;
      });
    }

    if (layers.traffic?.meshGroups) {
      layers.traffic.meshGroups.forEach((group) => {
        group.visible = settings.traffic;
      });
    }

    if (layers.weather?.meshGroups) {
      layers.weather.meshGroups.forEach((group) => {
        group.visible = settings.weather;
      });
    }
  }, [settings]);

  return <div ref={containerRef} className="w-full h-full" />;
}
